svg.script:
(function () {
  const root = document.currentScript.ownerDocument.documentElement;
  const hits = Array.from(root.querySelectorAll('.cut-hit, .tail-hit'));

  function selectCut(target) {
    const cut = target.dataset.cut;
    hits.forEach(el => {
      el.classList.toggle('is-selected', el.dataset.cut === cut);
    });

    root.dispatchEvent(new CustomEvent('cutlink:cut-selected', {
      detail: {
        cut: cut,
        id: target.id
      },
      bubbles: true
    }));
  }

  hits.forEach(el => {
    el.addEventListener('click', () => selectCut(el));
    el.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        selectCut(el);
      }
    });
  });
})();
